// GQ has no per-group limit (`limit` is global), so this returns every
// person's documents, newest first within each person. Keep the first three rows per person.
query recent_docs_per_person() {
    match {
        $p: Person
        $p authored $d
    }
    return { $p.handle, $p.name, $d.title, $d.year }
    order { $p.handle, $d.year desc }
}
